WITH valid AS (SELECT id, store_id, product_id, units, revenue, ADD_MONTHS(sale_date, 1) AS sale_date_plus_months, revenue - units AS revenue_per_unit FROM store_sales WHERE units >= 30), ranked AS (SELECT *, RANK() OVER (PARTITION BY store_id ORDER BY revenue_per_unit) AS row_num FROM valid QUALIFY row_num = 1), remaining_keys AS (SELECT product_id, store_id FROM ranked INTERSECT SELECT product_id, store_id FROM store_sales WHERE revenue > 3000), reconciled AS (SELECT s.* FROM ranked s INNER JOIN remaining_keys k ON s.product_id = k.product_id AND s.store_id = k.store_id), scored AS (SELECT *, DENSE_RANK() OVER (PARTITION BY product_id ORDER BY revenue_per_unit) AS revenue_per_unit_dense_rank, CUME_DIST() OVER (ORDER BY revenue_per_unit DESC NULLS LAST) AS revenue_per_unit_cume_dist FROM reconciled) SELECT product_id, COUNT(DISTINCT id) AS distinct_ids, APPROX_PERCENTILE(revenue_per_unit_cume_dist, 0.9) AS revenue_per_unit_cume_dist_p90, MIN(units) AS min_units FROM scored GROUP BY product_id ORDER BY min_units DESC NULLS FIRST;
